// TH15 v1.00b Stage 5 Boss1 nonspell. Source: st05bs.ecl.txt:50-82 (entry),
// 84-114 (Boss1_at), 116-164 (Boss1_at2), 8-34 (entry boxes/limit/position).
// Rank branches: the source difficulty masks are materialised per rank 0..3.
// Timing: phase timer starts on card frame 0; source enemy spawned after the
// 120-frame opening buffer. Source window 2400 from timerReset.
const TIME_LIMIT: int = 2524;
const OPENING_BUFFER: int = 120;

const TH15_BIG_BALL2: int = 656;   // source type 19
const TH15_BIG_STAR_R: int = 720;  // source type 23

const COLOR_SEED: int = 3;  // etSprite(0, 19, 3)
const COLOR_STAR: int = 1;  // etSprite(1, 23, 1)

// Seed bullet EX chain: ANIM(1) retreat is folded into the spawn offset,
// OFFSCREEN(120) -> offscreen_keep, WAIT(30) -> die at age 30 when the laser spawns.
xformdef SEED_LIFE {
    offscreen_keep(120);
    @30 add_speed(0fx);
    set_life(1);
}

// Source EX_LASER (a=1 infinite): sprite 38 / color 6, angle 90deg, length 640,
// speed 16 = length growth, timing startup/expand/hold/shrink 30/30/30/30,
// width 16 -> judged half-height 4. Target substitutes one constant-width,
// constant-length laser: judged length 0.9*640 = 576, judged width 2*4 = 8,
// warn=startup 30, active=expand+hold 60 (expand already collides), fade=30.
// Approximation: growth phase is drawn at final size from active start.
async sub seed_laser() {
    wait(29);
    _ = laser(6, $self_x, $self_y, 90deg, 576fx, 8fx, 30, 60, 30);
    wait(1);
}

// Boss1_at: fixed-direction 2-way fan (etAim 1), 5 shots on E/N and 6 on H/L.
// %A starts at 13.962634 rad (=800deg) and drops 0.174533 rad (10deg) per shot;
// the effective half spread is A/2 wrapped into +40..+15deg.
// %B starts at 4.0 and drops 0.4 per shot.
sub boss_at(rank: int) {
    var shots: int = 5;
    if rank >= RANK_HARD { shots = 6; }
    var a: int = 145636;      // 800deg in BAM
    var spd: fx = 4.0fx;
    for k in 0..shots {
        var half: int = a / 2 - 65536;
        var ang0: angle = -90deg + (half as angle);
        var ang1: angle = -90deg - (half as angle);
        // etDist(24) then ANIM position -= 4*velocity, both along the bullet angle.
        var dist: fx = 24fx - 4fx * spd;
        _ = fire(TH15_BIG_BALL2, COLOR_SEED,
                 $self_x + dist * cos(ang0), $self_y + dist * sin(ang0),
                 spd, ang0, SEED_LIFE, seed_laser);
        _ = fire(TH15_BIG_BALL2, COLOR_SEED,
                 $self_x + dist * cos(ang1), $self_y + dist * sin(ang1),
                 spd, ang1, SEED_LIFE, seed_laser);
        a = a - 1820;      // 10deg
        spd = spd - 0.4fx;
        wait(5);
    }
}

// Boss1_at2: one star per frame; etAim(1, 0) is an aimed fan, so each shot is
// fired at the direction from the boss to the player plus the sweeping offset.
// %A = +/-85.5deg + RANDF2*20deg once per sweep, 9deg per shot, 20 shots.
// The second sweep fires only on N/H/L (!NHL etOn); Easy still spends its 20 frames.
sub star_fire(offset_bam: int, spd: fx) {
    var ang: angle = aim_player() + (offset_bam as angle);
    var dist: fx = 24fx - 4fx * spd;   // etDist 24 + ANIM retreat
    _ = fire(TH15_BIG_STAR_R, COLOR_STAR,
             $self_x + dist * cos(ang), $self_y + dist * sin(ang),
             spd, ang, none, none);
}

async sub boss_at2(rank: int) {
    var sweeps: int = 3;               // diffI($B, 3, 5, 5, 5)
    if rank >= RANK_NORMAL { sweeps = 5; }
    var spd: fx = 3.0fx;               // E/N 3.0, H 3.8, L 4.3
    if rank == RANK_HARD { spd = 3.8fx; }
    if rank >= RANK_LUNATIC { spd = 4.3fx; }
    for rep in 0..sweeps {
        var a: int = 15565 + (rand(65536) - 32768) * 3641 / 32768;
        for i1 in 0..20 {
            star_fire(a, spd);
            a = a - 1638;              // -9deg
            wait(1);
        }
        var c: int = -15565 + (rand(65536) - 32768) * 3641 / 32768;
        for i2 in 0..20 {
            if rank >= RANK_NORMAL { star_fire(c, spd); }
            c = c + 1638;              // +9deg
            wait(1);
        }
    }
}

// moveRand(60, 4, 1.9): ABS direction chosen once from the current position and
// player x, then speed 1.9*(1-k/60) for k=1..60, clamped by moveLimit
// (0,128,280,64) -> x in [-140,140], y in [96,160]. Shared enemy slots:
// int0 = step count, fx0/fx1 = unit direction (cos/sin).
sub move_arm() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = ((60 - k) as fx / 60) * 1.9fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 96fx { ny = 96fx; }
    if ny > 160fx { ny = 160fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_begin(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    move_arm();
}

sub move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        move_arm();
    }
}

sub move_rand() {
    // R = pi*U in BAM; inner zone is moveLimit centre +/- width/4 = +/-70 for x.
    var r: int = rand(65536) - 32768;
    var a: int = 0;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 112fx {
        if a < 0 { a = -a; }
    } else if $self_y > 144fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    // Native +/-pi/2 guard, epsilon 0.05rad (nearest BAM boundaries).
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    move_begin(a as angle);
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);    // source setHitbox(48,48)
    set_hurtbox(20fx);   // source setHurtbox(40,40)
    var rank: int = global(GVAR_RANK);
    wait(60);            // Boss1 entry wait(60) before the first attack
    loop {
        boss_at(rank);
        spawn boss_at2(rank);   // source callAsync starts one frame later
        var gap: int = 120;     // !E !N 120; !H !L 100
        if rank >= RANK_HARD { gap = 100; }
        wait(gap);
        move_rand();
        move_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 17001, 0, 0, 0, boss_main);   // lifeSet(17001)
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
